#ifdef MACLOCK_COMBINED_SOURCE
static bool update_fireworks(ClockView &view, uint32_t frame) { static constexpr uint8_t kBurstFrames = 72; for (uint8_t burst = 0; burst < 3; ++burst) { const uint32_t shifted = frame + burst * 24, sequence = shifted / kBurstFrames; const uint8_t phase = shifted % kBurstFrames; const int cx = 38 + static_cast<int>((sequence * 83 + burst * 67) % 228), cy = 28 + static_cast<int>((sequence * 47 + burst * 31) % 104); if (phase < 14) { const int y = kExtHeight - 1 - (kExtHeight - cy) * phase / 14; line(view, cx, y, cx, min(kExtHeight - 1, y + 7)); continue; } const uint8_t age = phase - 14; if (age >= 48) continue; const int radius = 2 + age, gravity = age * age / 180; for (uint8_t i = 0; i < 32; i += age < 28 ? 1 : 2) { const float angle = i * 6.2831853f / 32.0f; put_pixel(view, cx + cosf(angle) * radius, cy + sinf(angle) * radius + gravity); if (age > 4 && !(i & 1)) put_pixel(view, cx + cosf(angle) * (radius - 3), cy + sinf(angle) * (radius - 3) + (age - 3) * (age - 3) / 180); } } return true; }
#endif
